package adminServer.mvp.company;
import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import adminServer.mvp.security.AuthenticatedUser;import adminServer.mvp.user.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;
@RestController @RequestMapping("/api/companies") public class CompanyController{private final CompanyRepository companies;private final CompanyMemberRepository members;private final UserRepository users;public CompanyController(CompanyRepository c,CompanyMemberRepository m,UserRepository u){companies=c;members=m;users=u;}@GetMapping public List<View> list(Authentication a){return companies.findAccessible(id(a)).stream().map(c->new View(c.getId(),c.getName())).toList();}@PostMapping @ResponseStatus(HttpStatus.CREATED)public View create(@Valid@RequestBody Create r,Authentication a){User u=users.findById(id(a)).orElseThrow();Company c=companies.save(new Company(r.name().trim(),u));members.save(new CompanyMember(c,u,UserRole.ADMIN));return new View(c.getId(),c.getName());}@PostMapping("/{companyId}/members")@ResponseStatus(HttpStatus.CREATED)public void member(@PathVariable UUID companyId,@Valid@RequestBody AddMember r,Authentication a){CompanyMember caller=members.findByCompanyIdAndUserId(companyId,id(a)).orElseThrow();if(caller.getRole()!=UserRole.ADMIN)throw new SecurityException("Somente administradores do espaço podem adicionar membros");User user=users.findByUsername(r.username().trim().toLowerCase()).orElseThrow();if(!members.existsByCompanyIdAndUserId(companyId,user.getId()))members.save(new CompanyMember(caller.getCompany(),user,r.role()));}private UUID id(Authentication a){return((AuthenticatedUser)a.getPrincipal()).id();}public record Create(@NotBlank@Size(max=120)String name){}public record AddMember(@NotBlank String username,@NotNull UserRole role){}public record View(UUID id,String name){}}
